import './App.css'
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';

// English pages
import HomeEn from './pages/en/home';
import AboutUsEn from './pages/en/about-us';
import ContactUsEn from './pages/en/contact-us'

// Swedish pages
import HomeSv from './pages/sv/home';
import AboutUsSv from './pages/sv/about-us';
import ContactUsSv from './pages/sv/contact-us'
import NotFound from './pages/404'

/*
 * Main App component with language-based routing using separate files
 * 
 * This approach uses dedicated files for each language version:
 * - English pages in ./pages/en/
 * - Swedish pages in ./pages/sv/
 * 
 * Benefits:
 * - Simple setup and maintenance
 * - No complex translation logic
 * - Fast performance (no runtime language switching)
 * - Easy content management
 * - SEO-friendly with static content
 * 
 * File structure:
 * pages/
 * ├── en/
 * │   ├── home.jsx
 * │   └── about-us.jsx 
 * ├── sv/
 * │   ├── home.jsx
 * │   └── about-us.jsx
 * └── contact-us.jsx
 * 
 * Usage examples:
 * - Navigate to English: <Link to="/en/home">Home</Link>
 * - Navigate to Swedish: <Link to="/sv/home">Hem</Link>
 * - Default language: Redirects / to /en/home
*/

function App() {
  return (
    <BrowserRouter>
      <Routes>
        {/* Default redirect to English */}
        <Route path="/" element={<Navigate to="/en/home" replace />} />
        
        {/* English routes */}
        <Route path="/en/home" element={<HomeEn />} />
        <Route path="/en/about-us" element={<AboutUsEn />} />
        <Route path="/en/contact-us" element={<ContactUsEn />} />
        
        {/* Swedish routes */}
        <Route path="/sv/home" element={<HomeSv />} />
        <Route path="/sv/about-us" element={<AboutUsSv />} />
        <Route path="/sv/contact-us" element={<ContactUsSv />} />
        
        {/* 404 fallback */}
        <Route path="*" element={<NotFound />} />
      </Routes>
    </BrowserRouter>
  )
}

export default App
